CREATE TYPE "RefundStatus" AS ENUM ('PENDING', 'PROCESSING', 'APPROVED', 'DENIED', 'ESCALATED', 'COMPLETED');
CREATE TYPE "DecisionType" AS ENUM ('APPROVED', 'DENIED', 'ESCALATED');
CREATE TABLE "Customer" ("id" TEXT NOT NULL, "publicId" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Customer_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Customer_publicId_key" ON "Customer"("publicId");
CREATE UNIQUE INDEX "Customer_email_key" ON "Customer"("email");
CREATE TABLE "Order" ("id" TEXT NOT NULL, "publicId" TEXT NOT NULL, "idempotencyKey" TEXT, "customerId" TEXT NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "status" TEXT NOT NULL DEFAULT 'DELIVERED', "orderDate" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Order_publicId_key" ON "Order"("publicId"); CREATE INDEX "Order_customerId_orderDate_idx" ON "Order"("customerId","orderDate");
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL, "orderId" TEXT NOT NULL, "productName" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "price" DECIMAL(12,2) NOT NULL, "finalSale" BOOLEAN NOT NULL DEFAULT false, "condition" TEXT NOT NULL DEFAULT 'NEW', CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId");
CREATE TABLE "RefundRequest" ("id" TEXT NOT NULL, "publicId" TEXT NOT NULL, "idempotencyKey" TEXT, "customerId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "message" TEXT NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "status" "RefundStatus" NOT NULL DEFAULT 'PENDING', "decision" "DecisionType", "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "RefundRequest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RefundRequest_publicId_key" ON "RefundRequest"("publicId"); CREATE UNIQUE INDEX "RefundRequest_idempotencyKey_key" ON "RefundRequest"("idempotencyKey"); CREATE INDEX "RefundRequest_status_createdAt_idx" ON "RefundRequest"("status","createdAt" DESC); CREATE INDEX "RefundRequest_customerId_createdAt_idx" ON "RefundRequest"("customerId","createdAt" DESC); CREATE INDEX "RefundRequest_orderId_idx" ON "RefundRequest"("orderId");
CREATE TABLE "PolicyEvaluation" ("id" TEXT NOT NULL, "refundRequestId" TEXT NOT NULL, "eligible" BOOLEAN NOT NULL, "flags" JSONB NOT NULL, "rules" JSONB NOT NULL, "evaluatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PolicyEvaluation_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PolicyEvaluation_refundRequestId_key" ON "PolicyEvaluation"("refundRequestId");
CREATE TABLE "AIAnalysis" ("id" TEXT NOT NULL, "refundRequestId" TEXT NOT NULL, "classification" TEXT NOT NULL, "recommendation" "DecisionType" NOT NULL, "summary" TEXT NOT NULL, "customerResponse" TEXT NOT NULL, "flags" JSONB NOT NULL, "model" TEXT NOT NULL, "promptVersion" TEXT NOT NULL, "latencyMs" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AIAnalysis_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AIAnalysis_refundRequestId_key" ON "AIAnalysis"("refundRequestId");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL, "refundRequestId" TEXT NOT NULL, "event" TEXT NOT NULL, "actor" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AuditLog_refundRequestId_createdAt_idx" ON "AuditLog"("refundRequestId","createdAt");
ALTER TABLE "Order" ADD CONSTRAINT "Order_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PolicyEvaluation" ADD CONSTRAINT "PolicyEvaluation_refundRequestId_fkey" FOREIGN KEY ("refundRequestId") REFERENCES "RefundRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AIAnalysis" ADD CONSTRAINT "AIAnalysis_refundRequestId_fkey" FOREIGN KEY ("refundRequestId") REFERENCES "RefundRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_refundRequestId_fkey" FOREIGN KEY ("refundRequestId") REFERENCES "RefundRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;
